INSERT INTO categories (name, display_order, is_active, is_deleted, created_by, created_at)
SELECT 'Signature', 1, true, false, 'SYSTEM', CURRENT_TIMESTAMP
WHERE NOT EXISTS (SELECT 1 FROM categories WHERE name = 'Signature' AND is_deleted = false);

